import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
c = [1] * n
for i in range(1, n):
    if a[i] > a[i - 1]:
        c[i] = c[i - 1] + 1
for i in range(n - 2, -1, -1):
    if a[i] > a[i + 1] and c[i] <= c[i + 1]:
        c[i] = c[i + 1] + 1
print(sum(c))

